import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { reservaService } from '../../services/api';
import { quartoService } from '../../services/api';
import { clienteService } from '../../services/api';
import { pagamentoService } from '../../services/api';
import ErrorModal from '../common/ErrorModal';
import KPICards from './dashboard/KPICards';
import ChartBar from './dashboard/ChartBar';
import RoomStatus from './dashboard/RoomStatus';
import RecentActivities from './dashboard/RecentActivities';
import Alerts from './dashboard/Alerts';

interface DashboardStats {
  totalReservas: number;
  reservasAtivas: number;
  reservasFinalizadas: number;
  reservasCanceladas: number;
  totalQuartos: number;
  quartosDisponiveis: number;
  quartosOcupados: number;
  quartosManutencao: number;
  quartosSujo: number;
  totalClientes: number;
  clientesNovosMes: number;
  totalReceita: number;
  receitaMes: number;
  receitaHoje: number;
  ocupacaoAtual: number;
  ocupacaoMedia: number;
  ticketMedio: number;
}

interface RelatorioMensal {
  mes: string;
  reservas: number;
  receita: number;
  ocupacao: number;
}

interface AtividadeRecente {
  id: string;
  tipo: string;
  descricao: string;
  tempo: string;
  icone: string;
  cor: string;
}

interface Alerta {
  id: string;
  tipo: string;
  mensagem: string;
  severidade: 'baixa' | 'media' | 'alta';
  tempo: string;
}

const DashboardAdmin: React.FC = () => {
  const navigate = useNavigate();
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [relatorioMensal, setRelatorioMensal] = useState<RelatorioMensal[]>([]);
  const [atividadesRecentes, setAtividadesRecentes] = useState<AtividadeRecente[]>([]);
  const [alertas, setAlertas] = useState<Alerta[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [periodoRelatorio, setPeriodoRelatorio] = useState('6');
  const [showError, setShowError] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  useEffect(() => {
    carregarDadosDashboard();
  }, [periodoRelatorio]);

  const carregarDadosDashboard = async () => {
    setIsLoading(true);
    try {
      const [reservasData, quartosData, clientesData, pagamentosData] = await Promise.all([
        reservaService.listarReservas(),
        quartoService.listarQuartos(),
        clienteService.listarClientes(),
        pagamentoService.listarPagamentos()
      ]);

      const hoje = new Date();
      const mesAtual = hoje.getMonth();
      const anoAtual = hoje.getFullYear();

      const totalReservas = Array.isArray(reservasData) ? reservasData.length : 0;
      const reservasAtivas = Array.isArray(reservasData) ? reservasData.filter((r: any) => r.status === 'ATIVA').length : 0;
      const reservasFinalizadas = Array.isArray(reservasData) ? reservasData.filter((r: any) => r.status === 'FINALIZADA').length : 0;
      const reservasCanceladas = Array.isArray(reservasData) ? reservasData.filter((r: any) => r.status === 'CANCELADA').length : 0;

      const totalQuartos = Array.isArray(quartosData) ? quartosData.length : 0;
      const quartosDisponiveis = Array.isArray(quartosData) ? quartosData.filter((q: any) => q.status === 'DISPONIVEL').length : 0;
      const quartosOcupados = Array.isArray(quartosData) ? quartosData.filter((q: any) => q.status === 'OCUPADO').length : 0;
      const quartosManutencao = Array.isArray(quartosData) ? quartosData.filter((q: any) => q.status === 'MANUTENCAO').length : 0;
      const quartosSujo = Array.isArray(quartosData) ? quartosData.filter((q: any) => q.status === 'SUJO').length : 0;

      const totalClientes = Array.isArray(clientesData) ? clientesData.length : 0;
      const clientesNovosMes = Array.isArray(clientesData) ? clientesData.filter((c: any) => {
        const dataCliente = new Date(c.createdAt || 0);
        return dataCliente.getMonth() === mesAtual && dataCliente.getFullYear() === anoAtual;
      }).length : 0;

      const totalReceita = Array.isArray(pagamentosData) ? pagamentosData.reduce((acc: number, pgto: any) => {
        const valor = pgto.valor || pgto.valorTotal || 0;
        return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
      }, 0) : 0;

      const receitaMes = Array.isArray(pagamentosData) ? pagamentosData
        .filter((pgto: any) => {
          const dataPgto = new Date(pgto.dataPagamento || pgto.createdAt || 0);
          return dataPgto.getMonth() === mesAtual && dataPgto.getFullYear() === anoAtual;
        })
        .reduce((acc: number, pgto: any) => {
          const valor = pgto.valor || pgto.valorTotal || 0;
          return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
        }, 0) : 0;

      const receitaHoje = Array.isArray(pagamentosData) ? pagamentosData
        .filter((pgto: any) => {
          const dataPgto = new Date(pgto.dataPagamento || pgto.createdAt || 0);
          return dataPgto.toDateString() === hoje.toDateString();
        })
        .reduce((acc: number, pgto: any) => {
          const valor = pgto.valor || pgto.valorTotal || 0;
          return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
        }, 0) : 0;

      const quartosOcupadosHoje = Array.isArray(reservasData) ? reservasData.filter((r: any) => {
        const hoje = new Date();
        const checkIn = new Date(r.checkIn || 0);
        const checkOut = new Date(r.checkOut || 0);
        return hoje >= checkIn && hoje < checkOut && r.status === 'ATIVA';
      }).length : 0;

      const ocupacaoAtual = totalQuartos > 0 ? (quartosOcupadosHoje / totalQuartos) * 100 : 0;
      const ticketMedio = totalReservas > 0 ? totalReceita / totalReservas : 0;

      const diasNoMes = new Date(anoAtual, mesAtual + 1, 0).getDate();
      let totalOcupacaoDiaria = 0;
      if (Array.isArray(reservasData)) {
        for (let dia = 1; dia <= diasNoMes; dia++) {
          const dataDia = new Date(anoAtual, mesAtual, dia);
          const quartosOcupadosDia = reservasData.filter((r: any) => {
            const checkIn = new Date(r.checkIn || 0);
            const checkOut = new Date(r.checkOut || 0);
            return dataDia >= checkIn && dataDia < checkOut && r.status === 'ATIVA';
          }).length;
          totalOcupacaoDiaria += quartosOcupadosDia;
        }
      }
      const ocupacaoMedia = totalQuartos > 0 ? (totalOcupacaoDiaria / (diasNoMes * totalQuartos)) * 100 : 0;

      setStats({
        totalReservas, reservasAtivas, reservasFinalizadas, reservasCanceladas,
        totalQuartos, quartosDisponiveis, quartosOcupados, quartosManutencao, quartosSujo,
        totalClientes, clientesNovosMes, totalReceita, receitaMes, receitaHoje,
        ocupacaoAtual: isNaN(ocupacaoAtual) ? 0 : ocupacaoAtual, 
        ocupacaoMedia: isNaN(ocupacaoMedia) ? 0 : ocupacaoMedia, 
        ticketMedio: isNaN(ticketMedio) ? 0 : ticketMedio
      });

      gerarRelatorioMensal(Array.isArray(reservasData) ? reservasData : [], Array.isArray(pagamentosData) ? pagamentosData : [], Array.isArray(quartosData) ? quartosData : []);
      gerarAtividadesRecentes(Array.isArray(reservasData) ? reservasData : [], Array.isArray(quartosData) ? quartosData : []);
      gerarAlertas(Array.isArray(reservasData) ? reservasData : [], Array.isArray(quartosData) ? quartosData : []);

    } catch (error) {
      console.error('Erro ao carregar dados do dashboard:', error);
      setErrorMessage('Não foi possível carregar os dados do dashboard. Tente novamente.');
      setShowError(true);
    } finally {
      setIsLoading(false);
    }
  };

  const gerarRelatorioMensal = (reservas: any[], pagamentos: any[], quartos: any[]) => {
    try {
      const meses = [];
      const hoje = new Date();

      for (let i = parseInt(periodoRelatorio) - 1; i >= 0; i--) {
        const data = new Date(hoje.getFullYear(), hoje.getMonth() - i, 1);
        const mesNome = data.toLocaleDateString('pt-BR', { month: 'short', year: 'numeric' });

        const reservasMes = reservas.filter((r: any) => {
          const dataReserva = new Date(r.createdAt || r.checkIn || 0);
          return dataReserva.getMonth() === data.getMonth() && 
                 dataReserva.getFullYear() === data.getFullYear();
        });

        const receitaMes = pagamentos
          .filter((pgto: any) => {
            const dataPgto = new Date(pgto.dataPagamento || pgto.createdAt || 0);
            return dataPgto.getMonth() === data.getMonth() && 
                   dataPgto.getFullYear() === data.getFullYear();
          })
          .reduce((acc: number, pgto: any) => {
            const valor = pgto.valor || pgto.valorTotal || 0;
            return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
          }, 0);

        const diasNoMes = new Date(data.getFullYear(), data.getMonth() + 1, 0).getDate();
        let totalOcupacaoDiaria = 0;

        for (let dia = 1; dia <= diasNoMes; dia++) {
          const dataDia = new Date(data.getFullYear(), data.getMonth(), dia);
          const quartosOcupadosDia = reservas.filter((r: any) => {
            const checkIn = new Date(r.checkIn || 0);
            const checkOut = new Date(r.checkOut || 0);
            return dataDia >= checkIn && dataDia < checkOut && r.status === 'ATIVA';
          }).length;
          totalOcupacaoDiaria += quartosOcupadosDia;
        }

        const ocupacaoMedia = quartos.length > 0 
          ? (totalOcupacaoDiaria / (diasNoMes * quartos.length)) * 100 
          : 0;

        meses.push({
          mes: mesNome,
          reservas: reservasMes.length,
          receita: isNaN(receitaMes) ? 0 : receitaMes,
          ocupacao: isNaN(ocupacaoMedia) ? 0 : Math.round(ocupacaoMedia * 10) / 10
        });
      }

      setRelatorioMensal(meses);
    } catch (error) {
      console.error('Erro ao gerar relatório mensal:', error);
      setRelatorioMensal([]);
    }
  };

  const gerarAtividadesRecentes = (reservas: any[], quartos: any[]) => {
    const atividades: AtividadeRecente[] = [];
    const agora = new Date();

    // Últimas reservas criadas
    reservas
      .sort((a: any, b: any) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime())
      .slice(0, 5)
      .forEach((reserva: any) => {
        const dataReserva = new Date(reserva.createdAt || 0);
        const diffMs = agora.getTime() - dataReserva.getTime();
        const diffMin = Math.floor(diffMs / (1000 * 60));
        const diffHoras = Math.floor(diffMin / 60);
        const diffDias = Math.floor(diffHoras / 24);

        let tempo = '';
        if (diffMin < 5) tempo = 'Agora';
        else if (diffMin < 60) tempo = `${diffMin} min atrás`;
        else if (diffHoras < 24) tempo = `${diffHoras}h atrás`;
        else tempo = `${diffDias} dia(s) atrás`;

        const clienteNome = reserva.cliente?.nome || reserva.nomeCliente || 'Cliente';
        const reservaId = reserva.id || reserva.codigo || '000';

        atividades.push({
          id: reservaId,
          tipo: 'reserva',
          descricao: `Nova reserva #${reservaId} - ${clienteNome}`,
          tempo: tempo,
          icone: '📅',
          cor: 'text-blue-600'
        });
      });

    // Quartos que mudaram de status recentemente
    quartos
      .filter((q: any) => q.status === 'SUJO' || q.status === 'MANUTENCAO')
      .slice(0, 3)
      .forEach((quarto: any) => {
        const quartoNumero = quarto.numero || quarto.codigo || 'N/A';
        const quartoId = quarto.id || `quarto-${quartoNumero}`;
        const status = quarto.status || 'UNKNOWN';

        atividades.push({
          id: quartoId,
          tipo: status === 'SUJO' ? 'limpeza' : 'manutencao',
          descricao: `Quarto ${quartoNumero} - Status: ${status}`,
          tempo: 'Agora',
          icone: status === 'SUJO' ? '🧹' : '🔧',
          cor: status === 'SUJO' ? 'text-yellow-600' : 'text-red-600'
        });
      });

    // Check-ins recentes
    reservas
      .filter((r: any) => r.status === 'ATIVA')
      .sort((a: any, b: any) => new Date(b.checkIn || 0).getTime() - new Date(a.checkIn || 0).getTime())
      .slice(0, 2)
      .forEach((reserva: any) => {
        const dataCheckin = new Date(reserva.checkIn || 0);
        const diffMs = agora.getTime() - dataCheckin.getTime();
        const diffHoras = Math.floor(diffMs / (1000 * 60 * 60));
        const diffDias = Math.floor(diffHoras / 24);

        let tempo = '';
        if (diffHoras < 1) tempo = 'Agora';
        else if (diffHoras < 24) tempo = `${diffHoras}h atrás`;
        else tempo = `${diffDias} dia(s) atrás`;

        const quartoNumero = reserva.quarto?.numero || reserva.numeroQuarto || 'N/A';
        const reservaId = reserva.id || reserva.codigo || '000';

        atividades.push({
          id: `checkin-${reservaId}`,
          tipo: 'checkin',
          descricao: `Check-in #${reservaId} - Quarto ${quartoNumero}`,
          tempo: tempo,
          icone: '🏨',
          cor: 'text-green-600'
        });
      });

    // Pagamentos recentes
    const pagamentosRecentes = reservas
      .filter((r: any) => r.status === 'FINALIZADA')
      .sort((a: any, b: any) => new Date(b.updatedAt || b.createdAt || 0).getTime() - new Date(a.updatedAt || a.createdAt || 0).getTime())
      .slice(0, 2);

    pagamentosRecentes.forEach((reserva: any) => {
      const dataPagamento = new Date(reserva.updatedAt || reserva.createdAt || 0);
      const diffMs = agora.getTime() - dataPagamento.getTime();
      const diffHoras = Math.floor(diffMs / (1000 * 60 * 60));

      let tempo = '';
      if (diffHoras < 1) tempo = 'Agora';
      else if (diffHoras < 24) tempo = `${diffHoras}h atrás`;
      else tempo = `${Math.floor(diffHoras / 24)} dia(s) atrás`;

      const clienteNome = reserva.cliente?.nome || reserva.nomeCliente || 'Cliente';
      const reservaId = reserva.id || reserva.codigo || '000';

      atividades.push({
        id: `pagamento-${reservaId}`,
        tipo: 'pagamento',
        descricao: `Pagamento #${reservaId} - ${clienteNome}`,
        tempo: tempo,
        icone: '💳',
        cor: 'text-emerald-600'
      });
    });

    // Ordenar por data mais recente e limitar a 8 atividades
    atividades.sort((a, b) => {
      const tempoA = a.tempo.includes('Agora') ? 0 : a.tempo.includes('min') ? 1 : a.tempo.includes('h') ? 2 : 3;
      const tempoB = b.tempo.includes('Agora') ? 0 : b.tempo.includes('min') ? 1 : b.tempo.includes('h') ? 2 : 3;
      return tempoA - tempoB;
    });

    setAtividadesRecentes(atividades.slice(0, 8));
  };

  const gerarAlertas = (reservas: any[], quartos: any[]) => {
    const novosAlertas: Alerta[] = [];
    const agora = new Date();

    const quartosSujo = quartos.filter((q: any) => q.status === 'SUJO').length;
    if (quartosSujo > 0) {
      novosAlertas.push({
        id: 'quartos-sujos',
        tipo: 'limpeza',
        mensagem: `${quartosSujo} quarto(s) precisam de limpeza`,
        severidade: 'media',
        tempo: 'Agora'
      });
    }

    const ocupacaoAtual = quartos.length > 0 ? (quartos.filter((q: any) => q.status === 'OCUPADO').length / quartos.length) * 100 : 0;
    if (ocupacaoAtual < 30) {
      novosAlertas.push({
        id: 'baixa-ocupacao',
        tipo: 'ocupacao',
        mensagem: `Taxa de ocupação baixa: ${ocupacaoAtual.toFixed(1)}%`,
        severidade: 'baixa',
        tempo: 'Hoje'
      });
    }

    const reservasHoje = reservas.filter((r: any) => {
      const checkIn = new Date(r.checkIn);
      return checkIn.toDateString() === agora.toDateString() && r.status === 'RESERVADA';
    }).length;

    if (reservasHoje > 0) {
      novosAlertas.push({
        id: 'checkins-hoje',
        tipo: 'checkin',
        mensagem: `${reservasHoje} check-in(s) agendado(s) para hoje`,
        severidade: 'baixa',
        tempo: 'Hoje'
      });
    }

    setAlertas(novosAlertas.slice(0, 4));
  };

  const formatarDataHora = (data: Date) => {
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(data);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-cyan-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 flex items-center justify-center">
        <div className="text-center">
          <div className="relative">
            <div className="animate-spin rounded-full h-20 w-20 border-4 border-indigo-200 dark:border-indigo-800 border-t-indigo-600"></div>
            <div className="absolute inset-0 rounded-full h-20 w-20 border-4 border-transparent border-t-indigo-400 animate-ping"></div>
          </div>
          <p className="mt-8 text-xl font-semibold text-gray-600 dark:text-gray-300">Carregando dashboard...</p>
        </div>
      </div>
    );
  }

  const maxReservas = Math.max(...relatorioMensal.map(r => r.reservas), 10);
  const maxReceita = Math.max(...relatorioMensal.map(r => r.receita), 1000);
  const maxOcupacao = 100;

  const reservasChartData = relatorioMensal.map(r => ({
    mes: r.mes,
    value: r.reservas
  }));

  const receitaChartData = relatorioMensal.map(r => ({
    mes: r.mes,
    value: r.receita
  }));

  const ocupacaoChartData = relatorioMensal.map(r => ({
    mes: r.mes,
    value: r.ocupacao
  }));

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-cyan-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 p-4 md:p-6">
      <div className="mb-8">
        <div className="bg-white/80 dark:bg-gray-800/80 backdrop-blur-xl rounded-2xl shadow-xl border border-white/20 dark:border-gray-700/50 p-6">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div>
              <h1 className="text-4xl font-bold bg-gradient-to-r from-indigo-600 to-cyan-600 bg-clip-text text-transparent">
                Dashboard Administrativo
              </h1>
              <p className="text-gray-600 dark:text-gray-400 mt-2 text-lg">
                Visão geral do hotel • {formatarDataHora(new Date())}
              </p>
            </div>
            <div className="flex items-center space-x-4">
              <select
                value={periodoRelatorio}
                onChange={(e) => setPeriodoRelatorio(e.target.value)}
                className="px-6 py-3 border border-gray-300 dark:border-gray-600 rounded-xl bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent shadow-sm hover:shadow-md transition-all duration-200"
              >
                <option value="3">Últimos 3 meses</option>
                <option value="6">Últimos 6 meses</option>
                <option value="12">Últimos 12 meses</option>
              </select>
            </div>
          </div>
        </div>
      </div>

      <KPICards stats={stats} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
        <ChartBar
          title="Reservas Mensais"
          data={reservasChartData}
          color="text-blue-600"
          maxValue={maxReservas}
          gradientId="reservasGradient"
        />
        <ChartBar
          title="Receita Mensal"
          data={receitaChartData}
          color="text-emerald-600"
          maxValue={maxReceita}
          unit="BRL"
          gradientId="receitaGradient"
        />
        <ChartBar
          title="Taxa de Ocupação"
          data={ocupacaoChartData}
          color="text-purple-600"
          maxValue={maxOcupacao}
          unit="%"
          gradientId="ocupacaoGradient"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <RoomStatus stats={stats} />
        </div>
        <div className="space-y-6">
          <RecentActivities atividades={atividadesRecentes} />
          <Alerts alertas={alertas} />
        </div>
      </div>

      <ErrorModal
        isOpen={showError}
        onClose={() => setShowError(false)}
        title="Erro ao Carregar Dados"
        message={errorMessage}
      />
    </div>
  );
};

export default DashboardAdmin;
